 lo,hi=D(lo),D(hi)
 p=[lo]+[z for z in map(D,['39.47','58.33','59.33','60','61','74.33','75.33','120','121','200','201'])
          if lo<z<hi]+[hi]
 for a,b in zip(p,p[1:]):work(a,b,0)
 return count, str(worst)
