 printf("denominator %" PRIu64 "; M [%" PRId64 ",%" PRId64 "]; B3 [%" PRId64 ",%" PRId64 "]\n",(U)SCALE,m0,m1,b0,b1);
 U s0=0,w0=0,s1=0,w1=0; a0=0;e0=0;
 unsigned a=2;
