  if(p>2)check(a,p,s0,w0,s1,w1,m0,m1,b0,b1,a0,e0,g0,g1);
  s0+=SCALE/p;w0++;a0+=power0(p,&e0);
  s1+=lnr(p,1)/p;w1+=1+updiv(EPS,p);
