 for(unsigned i=0;i<4;i++){
  for(unsigned j=0;j<5;j++)printf("%u %u last possibly failing cell ends at %" PRIu64 "; violation witness %" PRIu64 "\n",i,marg[i][j],last[i][j],witnesses[i][j]);
 }
}

