def pars(s):
 p=Q(8,3)*(1-s); q=5-2*s; d=1-p
 A=I('4.9')*powq(I(3),p)
 B=I('51.5')
 if not RAM_ONLY and s>=Q('.70'):
  c=I(ct[max(k for k in ct if Q(k,1000)<=s)])
  if (A-c).a>=0:A=c;B=I(5)
