  for j in range(8):
   w=E(I(j),1)-E(I(j+1),1)
   ans+=u/(u-(j+1))**2*w*btheta(lo-j-1,hi-j,idx)
  return mn(old,ans)
 v=u-16
 pre=prefix(u,v)
 if hi-16<=D('58.33'):
  pre=mn(pre,I('.08')*u*ex(v/2-u)+1255*u*E(u,1))
