bs=[sum(aa[j]*aa[k-j] for j in range(m+1) if 0<=k-j<=m) for k in range(2*m+1)]
cs=[sum(aa[j]*comb(k,j) for j in range(k+1))-bs[k] for k in range(m+1)]
