          1/(u**(m+1)*(1-2*(m+2)/u)))
def poly(u,order):return sum((cs[k]/u**(k-4) for k in range(4,5+order)),I(0))
@lru_cache(None)
def normerr(lo,hi,idx):
 u=I(lo,hi); v=u-1
 pup=e_pi(lo,hi,idx); pdn=e_pi(lo-1,hi-1,idx)
 if hi<=D('39.47'):pup=mn(pup,3*u*E(u,1))
 if lo>=120:pup=mn(pup,tail_pi_end(u,idx))
 if lo-1>=120:pdn=mn(pdn,tail_pi_end(v,idx))
 eu=pup+2500*u*E(u,1)+rem(u)
 el=pdn+2500*v*E(v,1)
 return u**4*(eu*(2*A(u)+eu)+u/v*el)
def gap(lo,hi,idx,order=-1):
 u=I(lo,hi)
 ls=sum((cs[k]/u**(k-4) for k in range(5+order,m+1)),I(0))
 ls-=sum((bs[k]/u**(k-4) for k in range(m+1,2*m+1)),I(0))
 return ls-normerr(lo,hi,idx)
def tail_pi_end(u,idx,s0=745):
 g,w,w0=grid(BETA[idx],s0)
 b=(I('.04')*u*u+13*u+2)*E(u,Q(1,2))+pp(u)+u*u/50*E(u,1-g[0])
 b+=sum((c*E(u,1-s) for s,c in zip(g[1:],w)),I(0))
 return b*(1+12/u)+prefix(u,u/2)
def tail_err(u,idx):
 u=I(u);v=u-1
 eu=tail_pi_end(u,idx)+2500*u*E(u,1)+rem(u)
 el=tail_pi_end(v,idx)+2500*v*E(v,1)
 return u**4*(eu*(2*A(u)+eu)+u/v*el)
def tail_prove(start,idx,order=-1,margin='0'):
 u=I(start);assert start>=240 and order<=7
 if order==-1:k=0;lead=1-I(margin)
 else:k=order+1;lead=I(cs[4+k])
 loss=sum((bs[j]/u**(j-4) for j in range(m+1,2*m+1)),I(0))+tail_err(u,idx)
 loss=loss*u**k
 assert (lead-loss).a>0, (start,idx,order,lead-loss)
 return str((lead-loss).a)

CASES=[
 ('37','240',0,-1,'.1'),('40.5','240',0,-1,'.5'),('42.15','240',0,-1,'.9'),
 ('42.8','240',0,-1,'1'),('47.5','240',0,1,'14'),('48','240',0,1,'19'),
 ('53','240',1,1,'80'),('48','240',1,1,'39'),
 ('217','250',0,2,'0'),('186','245',1,2,'0'),
 ('252','255',0,3,'0'),('210.2','240',1,3,'0'),
 ('287','290',0,4,'0'),('236','245',1,4,'0'),
 ('322','325',0,5,'0'),('262','265',1,5,'0'),
 ('357','361',0,6,'0'),('288','291',1,6,'0'),
 ('394','400',0,7,'0'),('318','320',1,7,'0'),
 ('200','250',0,1,'115'),('200','250',1,2,'1200'),
 ('240','270',0,2,'1300'),('240','270',1,4,'60000')]
def cutoff(lo,hi,check):
 # Adaptive rational subdivisions.  Each successful leaf is an entire-cell proof.
 count=0;worst=None
 def work(a,b,depth):
  nonlocal count,worst
  z=check(a,b)
  if z>0:
   count+=1;worst=z if worst is None else min(worst,z);return
  if a==b or depth==18:raise AssertionError(('cell failure',a,b,z))
  v=(a+b)/2;work(a,v,depth+1);work(v,b,depth+1)
 # Include subinterval boundaries on both sides, with validity by each enclosure.
 lo,hi=D(lo),D(hi)
 p=[lo]+[z for z in map(D,['39.47','58.33','59.33','60','61','74.33','75.33','120','121','200','201'])
          if lo<z<hi]+[hi]
 for a,b in zip(p,p[1:]):work(a,b,0)
 return count, str(worst)
def tail_case(at,idx,k,d):
 u=I(at);assert at>=240
 if k==-1 and D(d)==1:n=1;lead=I(14)
 elif k==-1:n=0;lead=1-I(d)
 else:n=k+1;lead=I(cs[4+n])-I(d)
 loss=u**n*(tail_err(u,idx)+sum((bs[j]/u**(j-4) for j in range(m+1,2*m+1)),I(0)))
 assert (lead-loss).a>0, (at,idx,k,d,lead-loss)
 return str((lead-loss).a)
def rcheck():
 aux()
 for a,b,idx,k,d in CASES:
  check=lambda u,v:(gap(u,v,idx,k)-I(d)/(I(u,v)**(k+1))).a
  fin=cutoff(a,b,check) if a!=b else None
  print('R ray',a,idx,k,d,'join',b, fin,tail_case(int(b),idx,k,d),flush=True)
 for a,b,k,d in [('36.9','37',-1,'0'),('53','125',2,'0'),('58','91',3,'0'),('65','71',4,'0')]:
  print('R bounded',a,b,k,cutoff(a,b,lambda u,v:(gap(u,v,0,k)-I(d)/I(u,v)**(k+1)).a),flush=True)

SIGN=D('43.74')
@lru_cache(None)
def ep(lo,hi,idx,upper):
 u=I(lo,hi)
 if upper and hi<=SIGN:return 3*u*E(u,1)
 old=e_pi(lo,hi,idx)
 if lo>=121:return mn(old,term(u,idx))
 if hi>67:return old
 # One-sided Chebyshev prefix and quarter-unit cells near the early joins.
 N=32 if hi<=D('58.33') else 64
 v=u-D(N)/4
 if upper and hi-D(N)/4<=SIGN:pre=3*u*E(u,1)
 elif hi-D(N)/4<=D('58.33'):
  pre=I('.08')*u*ex(v/2-u)+1255*u*E(u,1)
 else:pre=prefix(u,v)
 z=btheta(lo,hi,idx)+pre
 for k in range(N):
  x=D(k)/4;y=x+D('.25')
  if upper and hi-x<=SIGN:continue
  z+=u*(E(I(x),1)-E(I(y),1))/(u-y)**2*btheta(lo-y,hi-x,idx)
 return mn(old,z)

def term(u,idx):
 # Refined monotone analytic tail, applicable for u>=120.
 assert u.a>=120
 b=(I('.04')*u*u+13*u+2)*E(u,Q('.5'))+pp(u)+u*u/50*E(u,Q('.255'))
 b+=spectral(u,idx,7450,5)*E(u,1-BETA[idx])
 return b*(1+1/(u/3-4))+prefix(u,u/2)
def loss(lo,hi,idx,tail=False):
 u=I(lo,hi);v=u-1
 U=term(u,idx) if tail else ep(lo,hi,idx,True)
 Dn=term(v,idx) if tail else ep(lo-1,hi-1,idx,False)
 eu=U+2500*u*E(u,1)+rem(u);el=Dn+2500*v*E(v,1)
 return u**4*(eu*(2*A(u)+eu)+u/v*el)
def shell(u,order,tail=False):
 return (I(0) if tail else sum((cs[k]/u**(k-4) for k in range(5+order,m+1)),I(0)))-sum((bs[k]/u**(k-4) for k in range(m+1,2*m+1)),I(0))
def Grem(lo,hi,idx,k):
 u=I(lo,hi)
 return shell(u,k)-loss(lo,hi,idx)
def tay(L,idx,k,d):
 u=I(L)
 assert L>=121 and L-1>8*(4+k+1+3)
 n=k+1;lead=I(cs[4+n])-I(d)
 out=lead+(shell(u,k,True)-loss(u.a,u.b,idx,True))*u**n
 return out.a
def high(L,idx,n):
 old=higher.tail_pi_end
 try:
  higher.tail_pi_end=term
  return higher.high(L,idx,n)
 finally:higher.tail_pi_end=old

