  print('extension',a,b,k,d,cutoff(a,b,lambda u,v:(Grem(u,v,0,k)-I(d)/I(u,v)**(k+1)).a),flush=True)
 cases=[('48',1,1,'42',240),('53',1,1,'82',240),
        ('200',0,1,'116.6',240),('200',1,2,'1240',240),
