 # T depends pointwise on u; capped before the original RH height.
 T=mn(E(u,Q(-1,2))/2,I(3000175332800))
 v=(T/(2*PIVAL)).ln()
 return PIVAL/(T-1)+PIVAL**2/(3*T**2)+(v*v/(2*PIVAL)-v/(6*PIVAL))*E(u,Q(1,2))
