 u=I(a,b);ls=[ch(u)+pp(u)]
 if a>D('6.4') and b<=D('58.33'):ls.append(rh(u))
 if a>=34:ls.append(chopt(a,b)+pp(u))
 if a>=60:ls.append(zp(a,b,idx)+pp(u))
 if idx and a>=200:ls.append(D02(u)+pp(u))
